import React from "react";

function Education() {
  return (
    <section id="education" className="p-10 bg-gray-800 text-white">
      <h2 className="text-3xl font-bold mb-6">Education</h2>
      <ul className="list-disc ml-6">
        <li>MCA (Pursuing), Jamia Hamdard University, New Delhi</li>
        <li>BCA, Jamia Hamdard University, New Delhi — 2021</li>
        <li>Python Certificate Course, PCTI Institute — 2022</li>
        <li>Class XII (CBSE), Khalsa School, New Delhi — 2017</li>
        <li>Class X (NIOS), Guru Nanak Garib Niwaj School — 2015</li>
      </ul>
    </section>
  );
}

export default Education;
